int power(int a, int b, int m, int ans=1) {
    for(; b; b>>=1, a=1LL*a*a%m) if(b&1) ans=1LL*ans*a%m;
    return ans;
}

int dp[111];

int n, K;

int get(int u) {
    int ans=0;
    while(u) {
        ans += u%K;
        u /= K;
    }
    return ans % K;
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("in.in", "r", stdin);
    freopen("out.out", "w", stdout);
#endif
    cin >> n >> K;

    dp[0] = 1; // Empty subsequence

    for(int i=0; i<n; i++) {
        int u = get(i);
        // For each subsequence ending with a different digit, we can extend it with current element
        // Also count the new subsequence consisting of just current element
        int temp = dp[u];
        for(int j=0; j<K; j++) {
            if(j != u) {
                dp[u] = (dp[u] + dp[j]) % mod;
            }
        }
        // dp[u] already includes the new subsequence (the +1 is implicitly handled by dp[0]=1)
    }

    INT ans = 0;
    for(int i=0; i<K; i++) {
        ans = (ans + dp[i]) % mod;
    }

    println(ans);
    return 0;
}
